// Reconstructs a secrets provider config (the `cli`-equivalent of secrets.json) from a
// flat .env map of BRUNO_<PROVIDER_TYPE>_<FIELD> keys exported from the app's secret
// managers preferences. Returns { type, config } matching getExternalSecretsData, or
// null when no recognised provider keys are present.
//
// Key names come from @usebruno/common so this importer stays in lockstep with the
// app's exporter (Preferences → Secret Manager → Export as .env).

const { SECRET_PROVIDER_ENV_PREFIX, SECRET_PROVIDER_ENV_KEYS } = require('@usebruno/common');

const hasAnyKeyWithPrefix = (env, prefix) => Object.keys(env || {}).some((key) => key.startsWith(prefix));

const buildSecretsConfigFromEnv = (env = {}) => {
  if (hasAnyKeyWithPrefix(env, SECRET_PROVIDER_ENV_PREFIX['hashicorp-vault-server'])) {
    const k = SECRET_PROVIDER_ENV_KEYS['hashicorp-vault-server'];
    const method = env[k.AUTH_METHOD];
    const auth = { method };
    if (method === 'token') {
      auth.token = env[k.TOKEN];
    } else if (method === 'app_role') {
      auth.appRole = {
        role: env[k.APPROLE_ROLE],
        roleId: env[k.APPROLE_ROLE_ID],
        secretId: env[k.APPROLE_SECRET_ID],
        mountPath: env[k.APPROLE_MOUNT_PATH]
      };
    } else if (method === 'ldap') {
      auth.ldap = {
        username: env[k.LDAP_USERNAME],
        password: env[k.LDAP_PASSWORD]
      };
    }
    return {
      type: 'vault',
      config: {
        type: 'hashicorp-vault-server',
        vaultServerConfig: {
          url: env[k.URL],
          namespace: env[k.NAMESPACE],
          auth
        }
      }
    };
  }

  if (hasAnyKeyWithPrefix(env, SECRET_PROVIDER_ENV_PREFIX['hashicorp-vault-cloud'])) {
    const k = SECRET_PROVIDER_ENV_KEYS['hashicorp-vault-cloud'];
    return {
      type: 'vault',
      config: {
        type: 'hashicorp-vault-cloud',
        vaultCloudConfig: {
          auth: {
            method: env[k.AUTH_METHOD] || 'client_credentials',
            clientCredentials: {
              tokenEndpoint: env[k.TOKEN_ENDPOINT],
              secretsEndpoint: env[k.SECRETS_ENDPOINT],
              clientId: env[k.CLIENT_ID],
              clientSecret: env[k.CLIENT_SECRET]
            }
          },
          project: {
            organizationId: env[k.ORGANIZATION_ID],
            projectId: env[k.PROJECT_ID]
          }
        }
      }
    };
  }

  if (hasAnyKeyWithPrefix(env, SECRET_PROVIDER_ENV_PREFIX['aws-secrets-manager'])) {
    const k = SECRET_PROVIDER_ENV_KEYS['aws-secrets-manager'];
    return {
      type: 'aws-secrets-manager',
      config: {
        type: 'aws-secrets-manager',
        awsConfig: {
          authMethod: env[k.AUTH_METHOD],
          profileName: env[k.PROFILE_NAME],
          accessKeyId: env[k.ACCESS_KEY_ID],
          secretAccessKey: env[k.SECRET_ACCESS_KEY],
          sessionToken: env[k.SESSION_TOKEN],
          region: env[k.REGION]
        }
      }
    };
  }

  if (hasAnyKeyWithPrefix(env, SECRET_PROVIDER_ENV_PREFIX['azure-key-vault'])) {
    const k = SECRET_PROVIDER_ENV_KEYS['azure-key-vault'];
    return {
      type: 'azure-key-vault',
      config: {
        type: 'azure-key-vault',
        azureConfig: {
          tenantId: env[k.TENANT_ID],
          clientId: env[k.CLIENT_ID],
          clientSecret: env[k.CLIENT_SECRET]
        }
      }
    };
  }

  if (hasAnyKeyWithPrefix(env, SECRET_PROVIDER_ENV_PREFIX['gcp-secrets-manager'])) {
    const k = SECRET_PROVIDER_ENV_KEYS['gcp-secrets-manager'];
    return {
      type: 'gcp-secrets-manager',
      config: {
        type: 'gcp-secrets-manager',
        gcpConfig: {
          projectId: env[k.PROJECT_ID],
          clientEmail: env[k.CLIENT_EMAIL],
          privateKey: env[k.PRIVATE_KEY]
        }
      }
    };
  }

  return null;
};

module.exports = { buildSecretsConfigFromEnv };
